-- Generated from data/member4_manifest.csv
-- Tier-1 starter registry. Placeholder judgments remain quarantined and are not evidence.

on conflict (document_id) do update set
  title = excluded.title, document_type = excluded.document_type, jurisdiction = excluded.jurisdiction,
  court = excluded.court, bench = excluded.bench, authority = excluded.authority, citation = excluded.citation,
  case_number = excluded.case_number, case_year = excluded.case_year, document_date = excluded.document_date,
  section_or_article = excluded.section_or_article, parties = excluded.parties, language = excluded.language,
  source_url = excluded.source_url, file_name = excluded.file_name, status = excluded.status,
  source_tier = excluded.source_tier, metadata = excluded.metadata;
